res.format = function(obj) {
  var req = this.req;
  var type = req.headers['accept'];

  // Remove any charset or quality factors from the accept header
  type = type && type.split(';')[0];

  // If no type is specified, default to HTML
  if (!type) type = 'text/html';

  // If the object is not an object, assume it's a string and send it as the response
  if (typeof obj !== 'object') {
    this.send(obj);
    return;
  }

  // Iterate over the object keys to find a matching content type
  for (var key in obj) {
    if (obj.hasOwnProperty(key)) {
      // Check if the accept header matches the current key
      if (type === key || type.indexOf(key) === 0) {
        // Send the corresponding response
        this.send(obj[key]);
        return;
      }
    }
  }

  // If no matching content type is found, send a 406 Not Acceptable response
  this.status(406).send('Not Acceptable');
};

